# Boilerplate code partially generated by OVITO Pro 3.15.5
from pathlib import Path
import shutil

from ovito.io import import_file
from ovito.modifiers import (
    ExpressionSelectionModifier,
    DeleteSelectedModifier
)
from ovito.data import DataCollection
from ovito.vis import (
    Viewport,
    TextLabelOverlay,
    ColorLegendOverlay
)
from ovito.qt_compat import QtCore
from tce_modifier import TCEModifier
from tce.calculator import TCECalculator
from PIL import Image, ImageOps


IMAGES_DIR: Path = Path("images")


def generate_images():

    IMAGES_DIR.mkdir(exist_ok=True, parents=True)

    calc = TCECalculator.load("tmd-tce.pkl")

    for tce_id in range(49):

        print(tce_id)

        # ==== Set up pipeline ==== #

        # Data import:
        pipeline = import_file('ws2.xyz')

        # Edit simulation cell:
        def modify_cell(frame: int, data: DataCollection):
            data.cell_.pbc = (False, False, False)
        pipeline.modifiers.append(modify_cell)

        # Tensor cluster expansion:
        pipeline.modifiers.append(TCEModifier(
            neighbor_cutoffs = calc.neighbor_cutoffs, 
            many_body_features = [list(label) for label in calc.many_body_features], 
            neighbor_tolerance = calc.neighbor_tolerance, 
            visualize_cluster = tce_id, 
            cluster_bond_width = 0.3, 
            unwrap_cluster_bonds = True))

        # Expression selection:
        pipeline.modifiers.append(ExpressionSelectionModifier(
            expression = 'TCEClusterID!=5', 
            operate_on = 'bonds'))

        # Delete selected:
        pipeline.modifiers.append(DeleteSelectedModifier())

        # ======= Set up visual elements ======= #

        # Configure visual elements for pipeline
        try:
            data = pipeline.compute()
        except RuntimeError:
            continue
        data.particles.vis.scaling = 0.25
        data.particles.bonds.vis.width = 0.3

        cluster_type, = {label for label in data.attributes if f"(ID = {tce_id:0d})" in label}
        cluster_type = cluster_type.replace(f" (ID = {tce_id:0d})", "")
        composition, *neighbor_labels = cluster_type.split(" + ")
        unique_characters_in_composition = set(composition)
        for character in unique_characters_in_composition:
            if not character.isnumeric():
                continue
            if character == "1":
                to_replace = ""
            else:
                to_replace = rf"<sub>{character}</sub>"
            composition = composition.replace(character, to_replace)

        cluster_type = f"{composition} — {'+'.join(neighbor_labels)}"

        # Add pipelines to visualization scene
        pipeline.add_to_scene()

        # ========== Set up rendering ========== #

        # Viewport setup:
        viewport_layout = []

        # Viewport "Front":
        vp = Viewport()
        vp.type = Viewport.Type.Front
        vp.fov = 8.83143368394
        vp.camera_pos = [2.255647564295997, 0.0, 3.2114304305231145]
        vp.overlays.append(TextLabelOverlay(
            alignment = QtCore.Qt.AlignmentFlag.AlignHCenter | QtCore.Qt.AlignmentFlag.AlignBottom, 
            # offset_y = 0.02, 
            font_size = 0.04, 
            text = cluster_type, 
            pipeline = pipeline, 
            text_color = [0.0, 0.0, 0.0])
        )
        viewport_layout.append((vp, [0.0, 0.0, 0.5, 1.0]))  # [left,top,width,height]

        # Viewport "Perspective":
        vp = Viewport()
        vp.type = Viewport.Type.Perspective
        vp.fov = 0.610865238198
        vp.camera_dir = [-0.708108229221723, 0.5669062737307359, -0.42095131845999484]
        vp.camera_pos = [19.85672141441333, -9.969362955755342, 12.803261361348182]
        vp.camera_up = [-0.3286127254944541, 0.26308494665471566, 0.9070832307383883]

        vp.overlays.append(ColorLegendOverlay(
            alignment = QtCore.Qt.AlignmentFlag.AlignTrailing | QtCore.Qt.AlignmentFlag.AlignBottom, 
            offset_x = -0.033, 
            offset_y = 0.0378, 
            legend_size = 0.275, 
            font_size = 0.35, 
            label_size = 0.5, 
            title = ' ', 
            pipeline = pipeline, 
            property = "particles/Particle Type", 
            border_enabled = True))
        viewport_layout.append((vp, [0.5, 0.0, 0.5, 1.0]))  # [left,top,width,height]

        # Rendering:
        vp.render_image(filename=str(IMAGES_DIR / f'{tce_id}.png'), size=(1000, 500), layout=viewport_layout)
        pipeline.remove_from_scene()


def save_image_grid(
    grid_size: tuple[int, int],
    outline_width: int,
    output_path: Path = Path("grid.png"),
) -> Path:
    """
    Build a grid image from files in `image_dir` and save it to `output_path`.

    Args:
        image_dir: Directory containing image files.
        grid_size: (cols, rows)
        outline_width: Black border width around each image, in pixels.
        output_path: Where to save the final montage.

    Returns:
        The path to the saved grid image.
    """
    output_path = Path(output_path)
    cols, rows = grid_size

    if cols <= 0 or rows <= 0:
        raise ValueError("grid_size must be positive, e.g. (3, 4)")
    if outline_width < 0:
        raise ValueError("outline_width must be >= 0")

    # Load image files from the directory.
    valid_exts = {".png", ".jpg", ".jpeg", ".bmp", ".tif", ".tiff", ".webp"}
    paths = sorted(
        (p for p in IMAGES_DIR.iterdir()
        if p.is_file() and p.suffix.lower() in valid_exts),
        key=lambda path: int(path.stem)
    )

    if not paths:
        raise ValueError(f"No image files found in {IMAGES_DIR}")

    images = [Image.open(p).convert("RGB") for p in paths[: cols * rows]]

    # Compute a uniform inner cell size so every tile aligns nicely.
    max_w = max(img.width for img in images)
    max_h = max(img.height for img in images)
    cell_w = max_w + 2 * outline_width
    cell_h = max_h + 2 * outline_width

    grid_img = Image.new("RGB", (cols * cell_w, rows * cell_h), "white")

    for i in range(cols * rows):
        row, col = divmod(i, cols)
        x0 = col * cell_w
        y0 = row * cell_h

        if i >= len(images):
            continue  # Leave remaining cells blank white.

        img = images[i]

        # Fit image inside the cell while preserving aspect ratio.
        fitted = ImageOps.contain(img, (max_w, max_h), method=Image.Resampling.LANCZOS)

        # Add the black outline around the fitted image.
        bordered = ImageOps.expand(fitted, border=outline_width, fill="black")

        # Center the bordered image within its cell.
        paste_x = x0 + (cell_w - bordered.width) // 2
        paste_y = y0 + (cell_h - bordered.height) // 2
        grid_img.paste(bordered, (paste_x, paste_y))

    output_path.parent.mkdir(parents=True, exist_ok=True)
    grid_img.save(output_path)
    return output_path


if __name__ == "__main__":

    generate_images()
    out = save_image_grid(
        grid_size=(4, 5),
        outline_width=6,
        output_path=Path("figures") / "feature-grid.png",
    )
    print(f"Saved to {out}")
    shutil.rmtree(IMAGES_DIR)
